@c nlu.clause form=interrogative predicate="put" auxiliary="would" subject=$y direct_object=$p
@y nlu.entity pronoun="you"
@p nlu.entity name="Pack"
@r nlu.entity name="Refund"
@up nlu.relation kind=direction from=$p to=$r cue="up" adverb="diagonally"
@right nlu.relation kind=direction from=$p to=$r cue="right of"
@dirs nlu.coordination kind=additive member=$up member=$right cue="and"
